function App() {
  const [posts, setPosts] = useState([]);                  // state lives in App
  const addPost = (newPost) => {
    setPosts([...posts, newPost]);                         // function in App
  };
  return (
    <div>
      <PostList posts={posts} />                           // data flows down
      <PostForm onAddPost={addPost} />                     // function flows down
    </div>
  );
}

function PostList() {
  const [posts, setPosts] = useState([]);           // starts as an empty array
  useEffect(() => {                                 // runs after render
    const getData = async () => {
      const res = await fetch('https://api.example.com/posts');   // reaches OUTSIDE React
      const data = await res.json();
      setPosts(data);                               // brings data in -> re-render
    };
    getData();
  }, []);                                           // [] = only once
  return posts.map(post => <PostCard key={post.id} title={post.title} />);
}

